exercises.starter:
function sumTo(n) {
  // add up 1, 2, ..., n with a loop
}

exercises.solution:
function sumTo(n) {
  let total = 0
  for (let i = 1; i <= n; i++) total += i
  return total
}

function factorial(n) {
  let product = 1
  for (let i = 2; i <= n; i++) product *= i
  return product
}

exercises.starter:
function countMatching(arr, target) {
  // count how many elements equal target
}

exercises.solution:
function countMatching(arr, target) {
  let count = 0
  for (let i = 0; i < arr.length; i++) if (arr[i] === target) count++
  return count
}

exercises.starter:
function firstIndexOf(arr, target) {
  // return the index of the first match, or -1
}

exercises.solution:
function firstIndexOf(arr, target) {
  for (let i = 0; i < arr.length; i++) if (arr[i] === target) return i
  return -1
}

exercises.starter:
function collatzSteps(n) {
  // count steps to reach 1
}

exercises.solution:
function collatzSteps(n) {
  let steps = 0
  while (n !== 1) {
    n = n % 2 === 0 ? n / 2 : 3 * n + 1
    steps++
  }
  return steps
}
